from marshmallow import Schema, fields, ValidationError, pre_load, post_load, validates_schema

# post_load with field name
class S1(Schema):
    a = fields.Int()
    @post_load
    def err(self, item, **kwargs):
        raise ValidationError("bad", "a")
try:
    S1().load({"a": 1})
except ValidationError as e:
    assert e.messages == {"a": ["bad"]}, e.messages
    assert e.valid_data == {"a": 1}, e.valid_data

# pre_load error with many=True
class S2(Schema):
    a = fields.Int()
    @pre_load(pass_many=True)
    def err(self, items, **kwargs):
        raise ValidationError("nope")
try:
    S2(many=True).load([{"a": 1}])
except ValidationError as e:
    assert e.messages == {"_schema": ["nope"]}, e.messages
    assert e.valid_data is None

# field errors + schema validator with skip_on_field_errors=False -> both errors collected
class S3(Schema):
    a = fields.Int(required=True)
    @validates_schema(skip_on_field_errors=False)
    def v(self, data, **kwargs):
        raise ValidationError("schema err")
try:
    S3().load({})
except ValidationError as e:
    assert e.messages == {"a": ["Missing data for required field."], "_schema": ["schema err"]}, e.messages

# skip_on_field_errors=True -> schema validator skipped on field errors
class S4(Schema):
    a = fields.Int(required=True)
    @validates_schema
    def v(self, data, **kwargs):
        raise ValidationError("schema err")
try:
    S4().load({})
except ValidationError as e:
    assert e.messages == {"a": ["Missing data for required field."]}, e.messages

# unknown param validation
import pytest
try:
    S1().load({"a": 1}, unknown="badval")
    raise SystemExit("should have raised")
except ValueError as e:
    assert "not a valid value for the 'unknown' parameter" in str(e), e

# validate() returns all errors too
class S5(Schema):
    a = fields.Int(required=True)
    from marshmallow import validates
    @validates("a")
    def va(self, v):
        raise ValidationError("always bad")
assert S5().validate({"a": 1}) == {"a": ["always bad"]}
errs = S5().validate({})
assert errs == {"a": ["Missing data for required field."]}, errs
print("ALL OK")
